from book import Chapter
c=Chapter('16')
c.add('''一说到公平分配，讨论很容易立刻变成“每个人应该拿多少”。但是，在计算每个人应该拿多少之前，有一个更基本的问题需要先问清楚：我们准备分配的资源，究竟是拿来做什么的？

一个人吃一顿饭需要粮食，一座城市建立粮食储备也需要粮食；一个人住一套房屋需要空间，一整套交通和能源设施同样需要空间。两者使用的物质可能相同，所承担的功能却不同。如果把这两种用途混在一起，掌握公共生产资源的人就容易被理解为应该享有更多个人消费，而一个人提高生活质量的愿望，也容易被推成无限扩大支配权的理由。''')
c.heading('个人能够消费的东西，与共同体需要组织的东西')
c.src('R34498',start='5.当前文明制度中的这种幂律分配其实是有原因的',end='由他来领导团体，显然，比早期人类组织形式中的抽签法，以及平均投票法，具有更好的效果。',replacements=[('5.当前文明制度中的这种幂律分配其实是有原因的，对于一个团体来说','对于一个团体来说'),('而传统体制，无论是政治形式中的威权独裁，还是民主体制中的政党制中的多党轮流执政，其政府结构，以及商业公司的权力结构，本质上都是一种金字塔式的具有权力落差的层级结构','而传统政府和商业公司的许多组织结构，都是具有权力落差的层级结构'),('导致权力和财富的分配，都呈现幂律分配的长尾分布','容易使权力和财富的分配出现高度集中的长尾分布'),('在反复竞争下，获胜的决策领导者，是相对能力更强，决策的正确概率更高的个体。由他来领导团体，显然，比早期人类组织形式中的抽签法，以及平均投票法，具有更好的效果','如果通过竞争选择出能力更强、判断更准确的人，由他承担相应的协调工作，确实可能比不考虑能力差异的选择取得更好的效果。这是传统组织形式能够长期存在的一个原因')])
c.add('''问题出现在下一步：承担共同协调功能，为什么会变成协调者个人的永久特权？一个工程师能够帮助规划电网，因此应当认真听取他的专业判断，但电网所输送的能源不应该因此变成他个人可以任意处置的财产。同样，组织一次科研计划需要投入很多资源，这些投入的必要性来自研究任务，而不是项目负责人的个人生活需要。

把用途分开，才能进一步区分“我为了健康、学习和生活需要什么”，以及“我们为了共同完成一件事情需要组织什么”。前者需要理解具体的人；后者需要理解共同任务及其影响。''')
c.src('R54886',10,replacements=[('分配上还是我原来的意见：','在分配上，我主张：'),('对吧？',''),('如果完全按照一个人的本能驱使，也就是由他的生物生理和情绪来控制','如果完全按照即时冲动和刺激来选择')])
c.src('R34498',start='2.之所以我提到物质需要和精神需要的最佳边际效应',end='小说电影游戏再好，天天沉迷其中肯定也不好。',replacements=[('2.之所以我提到物质需要和精神需要的最佳边际效应','之所以要考察物质需要和精神需要的边际效用'),('从更抽象\n的层级来看','从更抽象的层级来看'),('这个过程中同类耗散结构体，不同个体之间其耗散的量的分布应该符合正态分布(就像人类的其他指标一样，比如身高，体重，力量，速度，智商)','不同个体在这个过程中的需要存在差异，也有可以观察和研究的范围，就像人的身高、体重、力量等指标有差异一样')])
c.add('''所以，按需并不等于平均分成一样多，也不等于谁能够喊出最大的数字就给谁最多。一个正在成长的孩子、一个成年人和一个需要特别照顾的人，生活条件和实际需要不同。把所有人塞进同一个消费额度，可能形式上很整齐，实际却不公平。

我用正态分布来帮助理解个体需要，关注的是人与人之间存在一定范围内的差异，而这种差异不等于财富和支配权可以无限累积。具体需要究竟怎样分布，仍然要看所讨论的资源和人群；不能先画出一条钟形曲线，再要求每个人把自己的生活塞进去。理解需要，是为了更好地满足人，而不是为了把人变成某个固定指标。''')
c.heading('为什么共同生产资源不能按个人消费来理解')
c.src('R34496',29,start='拿一个非常重要的资源来举例子：土地',end='相当于一个文明生命体的血液循环，呼吸系统，营养供给的新陈代谢系统。',replacements=[('，在中国土地的所有权是属于国家的，但是在西方，土地的所有权，归属个人，但是土地是','。土地是')])
c.add('''如果只从每一小块土地的单独用途出发，很难理解为什么需要一条穿过许多地方的铁路。可是，如果只强调铁路对整体有价值，又忽略沿线每个人的生活，这个“整体”就可能成为把损失推给部分人的借口。

两种分配放在一起，恰恰要求我们同时看到这两面：共同体需要组织基础设施，受影响的人也需要得到真正的照顾和参与。共同方案的计算，必须把他们的处境带进去，而不是把这些具体的人删去之后，才宣布得到了一个最优结果。

这也是为什么公共资源的支配需要共同智能。它不仅要计算建设效率，还要知道谁将受益，谁会受到影响，哪些影响能够避免，是否存在更好的替代方案。共同资源应该服务于整个共同体，而这个共同体由一个个具体的人组成。''')
c.src('R34498',start='4.但是，当前人类文明体制中',end='最终形成了权力财富资源分配的幂律分配这种情况。',replacements=[('4.但是，当前','而在当前'),('最终形成了权力财富资源分配的幂律分配这种情况','长期积累，就可能形成权力、财富和资源高度集中、差距越来越大的分配格局')])
c.src('R54886',29,replacements=[('现在的情况是：','在现行制度的许多场景中，'),('无论资本还是权力，基本上都被单个人或某些组织所支配','资本和权力由特定个人或组织支配')])
c.src('R34498',start='8.新架构中',replacements=[('8.新架构中','在我设想的新架构中'),('按需进行公平健康合理的正态分配','根据不同的需要进行公平、健康、合理的分配'),('哪种','那种')])
c.heading('贡献更多的人，为什么愿意参加')
c.src('R54886',40,end='文明内部破坏性张力。',replacements=[('任何人和团体，都会','许多人和团体，会'),('就能消除的','就能完全消除的')])
c.add('''这里有一个很容易被忽略的区别：占有更多资源，与真正获得更好的生活，并不总是同一件事。一个人拥有很高的地位，可能同时需要花费更多精力防范别人；一个组织掌握大量知识，也可能因为不愿与外部合作，而错过原本能够完成的创造。

如果一个新机制只能要求优势者放弃利益，却不能说明他们可以得到什么，那么它很难获得自愿参加。我的思路，是把眼前的占有与长期能够获得的生活条件放在一起考察。更好的合作能否创造出过去没有的能力？这些能力能否让每一个人，包括原本的优势者，也获得更大的收益？''')
c.src('R54886',40,start='而且这个机制最大的好处是',end='新财富。',replacements=[('而且这个机制最大的好处是，牺牲近期利益和暂时利益，获得了更大的长期利益和永久利益','这个机制所追求的一个好处，是通过调整近期和局部的利益关系，获得更大的长期利益'),('但实际上，首先个人生存资源上并没有遭受损失','如果个人需要得到了充分满足，那么在个人生存资源上并没有遭受损失'),('反而在更合理更健康更优化的分配下，你的物质和精神生活反而更健康','在更合理、更健康的分配下，物质和精神生活还可能得到改善'),('没有了与其他人之间的巨大财富差距下，防范他人的精神压力，让你更快乐','不必因为与他人之间的巨大财富差距而始终防范别人，精神压力也可能降低'),('这种新机制可以更快的让文明和科学进化','如果这种新机制能够更快地推进文明和科学的发展'),('给你带来更长期更永久让你更快乐幸福的新财富','就能带来过去没有的、让人更快乐幸福的新财富')])
c.add('''可以用一个思想实验，把这种选择放大到足够清楚。下面的寿命和技术时间只是假定，用来比较两种利益结构。''')
c.src('R54886',40,start='举个例子，你是世界首富',end='听听他们的选择。',replacements=[('举个例子，你是世界首富','假如你是世界首富'),('永生科技的实现需要40年的时间','一种能够大幅延长寿命的科技，需要40年才能实现'),('永生技术发明之前','这项技术实现之前'),('10万亿公共资源财富','10万亿用于生产和共同发展的资源财富'),('最棒的是，在这个新决策体系，新财富分配制度，新的社会进化体制下，永生科技在20年后就出现了，于是世界首富在80岁那年获得了永生','再假定，在新的决策体系、财富分配和合作方式下，这项科技在20年后就出现了，于是这位首富在80岁那年也能够使用它'),('将给','讲给')])
c.add('''这个例子所问的，不是我们今天能否给长寿技术排出一张准确的时间表，而是：当个人的收益取决于整个文明能创造什么时，维护独占权是否仍然是唯一有利的选择？一个人再富有，也不能购买尚未被发明的东西；如果更好的合作使这些东西更早出现，他可能从共同发展中得到比单独占有更多的收益。

当然，这个好处不能仅仅停留在许诺上。新机制需要从能够实际提供的服务开始，让参与者逐渐看见成本、体验和创造能力的变化。人们可以根据真实结果决定参与多少，而不是先放弃原有生活，再等待一个遥远的兑现。''')
c.heading('个人生活为什么不应由一次评分决定')
c.add('''回到这一章开始的问题。一个人参与某项共同判断，结果证明他错了，这可以改变我们对他在这个问题上的经验判断，却不应该让他失去吃饭、学习和生活的基本条件。否则，他就有很强的理由掩饰错误；在关系到生存的时候，记录真实失败会变成一种奢侈。

同样，一个人在某一领域做出了重大贡献，这个贡献应当被清楚记录，也应当帮助其他人理解他的能力。但如果它自动兑换成对所有领域的永久支配权，两种资源又被重新混在一起了。

把个人需求与共同资源分开，正是为了改变这种激励结构。生活的保障，使人有条件承认不知道、承认失败、尝试新方向；共同资源的使用，则根据共同任务、参与者意见和实际反馈来决定。这样，贡献、学习和纠错能够成为持续的过程，而不必把每一次讨论都变成争夺生存资格的比赛。''')
c.src('R54886',41,start='比如一个数学家有了关于某个问题或理论的一点开创性的想法',end='非常缓慢的实现。',replacements=[('比如一个','一个'),('在信息不透明，合作不充分，工作效率更低的情况下，非常缓慢的实现','在信息不透明、合作不充分、工作效率更低的情况下，非常缓慢地实现')])
c.add('''如果一个人不需要靠锁住这点新想法来保住自己的生活，贡献也不会因为与别人分享就被抹掉，那么他就更有理由尽早把问题放到共同网络中。别人可以完成自己擅长的部分，新的成果又能被更多人继续使用。这时，个人的安全感、知识的流动和共同生产能力，才开始朝着同一个方向相互加强。

所以，两种分配并不是理论之外附带的一项福利安排。它关系到参与者为什么愿意提供真实信息，为什么愿意合作，为什么能够承认错误，以及共同智能为什么有可能获得更充分的材料。它与动态权重、公共知识和开放组织，是同一个机制的不同部分。''')
c.save({'central_question':'为什么必须分开个人生活需要和共同生产资源的支配','reasoning':'用途区别→需要的差异与适量→共同资源的外部影响→不对等累积→优势者的长期收益→生活保障与真实反馈','examples':['个人饭食与城市储备','工程师与电网','营养及精神需要','铁路与沿线生活','首富与长寿技术的思想实验','数学家创业者游戏作者的信息保密'],'objections':['按需等于平均或无限索取','公共效率可以忽略个体','贡献多必须获得永久支配权','优势者没有参与理由'],'voice':'长篇保留两类资源、复利分化及长期利益的原话；思想实验数值保留但不冒充技术预测','status':'已逐段初校；正态分布改成待测分布及差异直觉，不作强制分配公式'})
